        const av = 0.35;
        vf.x += av * (v.x - vf.x);
        vf.y += av * (v.y - vf.y);
        vf.z += av * (v.z - vf.z);

        thrustLag += (lastThrust - thrustLag) * 0.22;

        if (p.y > 0.09) {
