      const prevRefX = ref.x, prevRefY = ref.y, prevRefZ = ref.z;
      const isCross = (obs.gateIndex < 3 && phase === 'cross') || lockedGate !== null;
      const maxStepXZ = isCross ? 0.024 : 0.020;
      const maxStepY = 0.016;
      const alphaRef = isCross ? 0.12 : 0.085;

      ref.x += clamp((target.x - ref.x) * alphaRef, -maxStepXZ, maxStepXZ);
      ref.y += clamp((target.y - ref.y) * alphaRef, -maxStepY, maxStepY);
      ref.z += clamp((target.z - ref.z) * alphaRef, -maxStepXZ, maxStepXZ);

      const vRefX = (ref.x - prevRefX) / dt;
      const vRefY = (ref.y - prevRefY) / dt;
      const vRefZ = (ref.z - prevRefZ) / dt;

      const rawEx = target.x - p.x;
      const rawEy = target.y - p.y;
      const rawEz = target.z - p.z;

      if (p.y > 0.085) {
        if (Math.abs(rawEx) < 0.35) intX = clamp(intX + rawEx * dt, -0.45, 0.45);
        else intX *= 0.95;

        if (Math.abs(rawEz) < 0.35) intZ = clamp(intZ + rawEz * dt, -0.45, 0.45);
        else intZ *= 0.95;

        if (Math.abs(rawEy) < 0.45) intY = clamp(intY + rawEy * dt, -0.60, 0.60);
        else intY *= 0.97;

        yawInt = clamp(yawInt + att.yaw * dt, -0.6, 0.6);
      }

      const ex = ref.x - p.x;
      const ey = ref.y - p.y;
      const ez = ref.z - p.z;

      const distX = clamp(0.80 * dFast.x + 0.20 * dSlow.x, -5.5, 5.5);
      const distZ = clamp(0.80 * dFast.z + 0.20 * dSlow.z, -5.5, 5.5);
      const distY = clamp(0.25 * dFast.y + 0.75 * dSlow.y, -4.5, 4.5);

      const kpZ = isCross ? 6.2 : 5.2;
      const kdZ = isCross ? 4.2 : 3.8;

      const ax = clamp(5.2 * ex + 3.8 * (0.60 * vRefX - vf.x) + 1.8 * intX + drag * vf.x - distX, -4.2, 4.2);
      const az = clamp(kpZ * ez + kdZ * (0.60 * vRefZ - vf.z) + 1.8 * intZ + drag * vf.z - distZ, -4.2, 4.2);
      const ay = clamp(6.0 * ey + 4.0 * (0.60 * vRefY - vf.y) + 2.2 * intY + drag * vf.y - distY, -3.5, 4.8);

      const aFwd = cy * ax - sy * az;
      const aRight = sy * ax + cy * az;

      const nearPadTouchdown = obs.gateIndex === 3 && p.y < 0.11 && Math.hypot(obs.pad.centre.x - p.x, obs.pad.centre.z - p.z) < 0.135;
      const maxTilt = nearPadTouchdown ? 0.13 : 0.48;

      const pitch = clamp(Math.atan2(aFwd, 9.81), -maxTilt, maxTilt);
      const roll = clamp(Math.atan2(-aRight, 9.81), -maxTilt, maxTilt);

      let thrust = clamp((m0 * (9.81 + ay)) / (16 * Math.max(0.68, dirY)), 0, 1);
      if (nearPadTouchdown && p.y <= 0.082 && Math.hypot(vf.x, vf.y, vf.z) < 0.25) {
        thrust = Math.min(thrust, 0.12);
      }
      lastThrust = thrust;

      const yawRate = clamp(-3.2 * att.yaw - 2.5 * yawInt - 0.25 * rates.yaw, -2, 2);
      return { thrust, roll, pitch, yawRate };
    },
  };
}

