export default function makeController() {
  const dt = 0.01;
  const m0 = 0.72;
  const drag = 0.42 / m0;
  const clamp = (v, lo, hi) => Math.max(lo, Math.min(hi, v));

  let init = false;
  let vf = { x: 0, y: 0, z: 0 };
  let prevVf = { x: 0, y: 0, z: 0 };
  let ref = { x: 0, y: 0, z: 0 };

  let dFast = { x: 0, y: 0, z: 0 };
  let dSlow = { x: 0, y: 0, z: 0 };
  let thrustLag = 0;
  let lastThrust = 0.45;

  let intX = 0, intY = 0, intZ = 0, yawInt = 0;

  let targetIndex = -1;
  let phase = 'align';
  let settle = 0;
  let activeGate = null;
  let lockedGate = null;
  let padY = 0.65;

  return {
    step(obs) {
      const p = obs.pos, v = obs.vel, att = obs.att, rates = obs.rates;

      const bodyX = Math.sin(att.pitch) * Math.cos(att.roll);
      const bodyZ = -Math.sin(att.roll);
      const cy = Math.cos(att.yaw), sy = Math.sin(att.yaw);
      const dirX = cy * bodyX + sy * bodyZ;
      const dirY = Math.cos(att.pitch) * Math.cos(att.roll);
      const dirZ = -sy * bodyX + cy * bodyZ;

      if (!init) {
        init = true;
        vf.x = v.x; vf.y = v.y; vf.z = v.z;
        prevVf.x = v.x; prevVf.y = v.y; prevVf.z = v.z;
        ref.x = p.x; ref.y = Math.max(p.y, 0.25); ref.z = p.z;
      } else {
        prevVf.x = vf.x; prevVf.y = vf.y; prevVf.z = vf.z;
        const av = 0.35;
        vf.x += av * (v.x - vf.x);
        vf.y += av * (v.y - vf.y);
        vf.z += av * (v.z - vf.z);

        thrustLag += (lastThrust - thrustLag) * 0.22;

        if (obs.t > 0.12 && p.y > 0.10) {
          const measAx = (vf.x - prevVf.x) / dt;
          const measAy = (vf.y - prevVf.y) / dt;
          const measAz = (vf.z - prevVf.z) / dt;

          const specThrust = (16 / m0) * thrustLag;
          const expAy = specThrust * dirY - 9.81 - drag * vf.y;
          const rawDy = clamp(measAy - expAy, -6, 6);
          dFast.y += 0.16 * (rawDy - dFast.y);
          dSlow.y += 0.025 * (rawDy - dSlow.y);

          const effSpecThrust = clamp(specThrust + dSlow.y / Math.max(0.7, dirY), 4, 24);
          const expAx = effSpecThrust * dirX - drag * vf.x;
          const expAz = effSpecThrust * dirZ - drag * vf.z;

          const rawDx = clamp(measAx - expAx, -8, 8);
          const rawDz = clamp(measAz - expAz, -8, 8);
          dFast.x += 0.20 * (rawDx - dFast.x);
          dFast.z += 0.20 * (rawDz - dFast.z);
          dSlow.x += 0.02 * (rawDx - dSlow.x);
          dSlow.z += 0.02 * (rawDz - dSlow.z);
        }
      }

      if (lockedGate && (p.x > lockedGate.x + 0.20 || p.x < lockedGate.x - 0.15)) {
        lockedGate = null;
      }

      if (obs.gateIndex !== targetIndex) {
        if (activeGate && obs.gateIndex > targetIndex && p.x <= activeGate.x + 0.20) {
          lockedGate = { x: activeGate.x, y: activeGate.y, z: activeGate.z };
        }
        targetIndex = obs.gateIndex;
        phase = 'align';
        settle = 0;
        if (obs.gateIndex === 3) {
          padY = clamp(p.y, 0.35, 0.70);
        }
      }

      let target;
      if (lockedGate) {
        target = { x: lockedGate.x + 0.36, y: lockedGate.y, z: lockedGate.z };
      } else if (obs.gateIndex < 3) {
        const gate = obs.nextGate.centre;
        activeGate = { x: gate.x, y: gate.y, z: gate.z };
        const eyA = Math.abs(gate.y - p.y);
        const ezA = Math.abs(gate.z - p.z);
        const alignX = (eyA > 0.22 || ezA > 0.16) ? gate.x - 0.50 : gate.x - 0.42;

        if (phase === 'align') {
          if (p.x > gate.x - 0.04) {
            if (eyA < 0.08 && ezA < 0.065) {
              target = { x: gate.x - 0.42, y: gate.y, z: gate.z };
            } else {
              target = { x: Math.max(p.x, gate.x + 0.25), y: gate.y, z: gate.z };
            }
            settle = 0;
          } else {
            target = { x: alignX, y: gate.y, z: gate.z };
            const exA = Math.abs((gate.x - 0.42) - p.x);
            const spd = Math.hypot(vf.x, vf.y, vf.z);
            const gustZ = Math.abs(dFast.z - dSlow.z);
            if (exA < 0.12 && eyA < 0.085 && ezA < 0.06 && spd < 0.30 && gustZ < 1.1) {
              settle++;
            } else {
              settle = Math.max(0, settle - 1);
            }
            if (settle >= 10) {
              phase = 'cross';
            }
          }
        }

        if (phase === 'cross') {
          const dxGate = gate.x - p.x;
          const stopDist = (vf.x > 0 ? (vf.x * vf.x) / 6.2 : 0) + Math.max(0, vf.x) * 0.05;
          if (dxGate > Math.max(0.08, stopDist)) {
            const tPred = clamp(dxGate / Math.max(vf.x, 0.30), 0.05, 0.28);
            const predY = (p.y - gate.y) + vf.y * tPred + 0.2 * (dFast.y - dSlow.y) * tPred * tPred;
            const predZ = (p.z - gate.z) + vf.z * tPred + 0.2 * (dFast.z - dSlow.z) * tPred * tPred;
            if (ezA > 0.082 || Math.abs(predZ) > 0.092 || eyA > 0.15 || Math.abs(predY) > 0.17) {
              phase = 'align';
              settle = 0;
              target = { x: gate.x - 0.44, y: gate.y, z: gate.z };
              ref.x = Math.min(ref.x, p.x - 0.12);
            }
          }
          if (phase === 'cross') {
            target = { x: gate.x + 0.38, y: gate.y, z: gate.z };
          }
        }
      } else {
        const pad = obs.pad.centre;
        const errH = Math.hypot(pad.x - p.x, pad.z - p.z);
        const spdH = Math.hypot(vf.x, vf.z);
        if (errH < 0.35) {
          const rate = (errH < 0.12 && spdH < 0.30) ? 0.0050 : (errH < 0.20 ? 0.0022 : 0.0010);
          const minY = (errH < 0.125 && spdH < 0.32) ? 0.015 : 0.18;
          padY = Math.max(minY, padY - rate);
        } else {
          padY = Math.max(0.32, Math.min(padY, 0.60));
        }
        target = { x: pad.x, y: padY, z: pad.z };
      }

      const isCross = (obs.gateIndex < 3 && phase === 'cross') || lockedGate !== null;
      const maxStepXZ = isCross ? 0.026 : 0.022;
      const maxStepY = 0.018;
      const alphaRef = isCross ? 0.14 : 0.09;

      ref.x += clamp((target.x - ref.x) * alphaRef, -maxStepXZ, maxStepXZ);
      ref.y += clamp((target.y - ref.y) * alphaRef, -maxStepY, maxStepY);
      ref.z += clamp((target.z - ref.z) * alphaRef, -maxStepXZ, maxStepXZ);

      const rawEx = target.x - p.x;
      const rawEy = target.y - p.y;
      const rawEz = target.z - p.z;

      if (p.y > 0.085) {
        if (Math.abs(rawEx) < 0.35) intX = clamp(intX + rawEx * dt, -0.45, 0.45);
        else intX *= 0.95;

        if (Math.abs(rawEz) < 0.35) intZ = clamp(intZ + rawEz * dt, -0.45, 0.45);
        else intZ *= 0.95;

        if (Math.abs(rawEy) < 0.45) intY = clamp(intY + rawEy * dt, -0.60, 0.60);
        else intY *= 0.97;

        yawInt = clamp(yawInt + att.yaw * dt, -0.6, 0.6);
      }

      const ex = ref.x - p.x;
      const ey = ref.y - p.y;
      const ez = ref.z - p.z;

      const distX = clamp(0.75 * dFast.x + 0.25 * dSlow.x, -5.0, 5.0);
      const distZ = clamp(0.75 * dFast.z + 0.25 * dSlow.z, -5.0, 5.0);
      const distY = clamp(0.25 * dFast.y + 0.75 * dSlow.y, -4.5, 4.5);

      const kpZ = isCross ? 5.8 : 4.8;
      const kdZ = isCross ? 4.0 : 3.6;

      const ax = clamp(4.8 * ex - 3.6 * vf.x + 1.8 * intX + drag * vf.x - distX, -3.5, 3.5);
      const az = clamp(kpZ * ez - kdZ * vf.z + 1.8 * intZ + drag * vf.z - distZ, -3.8, 3.8);
      const ay = clamp(6.0 * ey - 3.8 * vf.y + 2.2 * intY + drag * vf.y - distY, -3.5, 4.8);

      const aFwd = cy * ax - sy * az;
      const aRight = sy * ax + cy * az;

      const nearPadTouchdown = obs.gateIndex === 3 && p.y < 0.11 && Math.hypot(obs.pad.centre.x - p.x, obs.pad.centre.z - p.z) < 0.135;
      const maxTilt = nearPadTouchdown ? 0.13 : 0.46;

      const pitch = clamp(Math.atan2(aFwd, 9.81), -maxTilt, maxTilt);
      const roll = clamp(Math.atan2(-aRight, 9.81), -maxTilt, maxTilt);

      let thrust = clamp((m0 * (9.81 + ay)) / (16 * Math.max(0.68, dirY)), 0, 1);
      if (nearPadTouchdown && p.y <= 0.082 && Math.hypot(vf.x, vf.y, vf.z) < 0.25) {
        thrust = Math.min(thrust, 0.12);
      }
      lastThrust = thrust;

      const yawRate = clamp(-3.2 * att.yaw - 2.5 * yawInt - 0.25 * rates.yaw, -2, 2);
      return { thrust, roll, pitch, yawRate };
    },
  };
}

