  for (const h of hist.slice(-15)) console.log(`  t=${h.t} pos=(${h.pos.x.toFixed(3)},${h.pos.y.toFixed(3)},${h.pos.z.toFixed(3)}) vel=(${h.vel.x.toFixed(2)},${h.vel.y.toFixed(2)},${h.vel.z.toFixed(2)}) att=(${h.att.roll.toFixed(2)},${h.att.pitch.toFixed(2)}) gate=${h.gate}`);
