          } else {
            targetX = alignX; targetY = gy; targetZ = gz;
            if (px > gx - 0.26 && (ezA > 0.075 || eyA > 0.14 || vfX > 0.20)) {
              targetX = gx - 0.54;
              refX = targetX;
              emergencyBrakeX = true;
