      const az = clamp(kpZ * ez - kdZ * vfZ + 1.8 * intZ + drag * vfZ - distZ, -4.2, 4.2);
      const ay = clamp(6.0 * ey - 3.8 * vfY + 2.2 * intY + drag * vfY - distY, -3.5, 4.8);

