      const lowAlt = obs.gateIndex === 3 && py < 0.17;
      const maxTilt = nearPadTouchdown ? 0.13 : (lowAlt ? 0.26 : ((emergencyBrakeX || exitBoostX) ? 0.52 : 0.46));

