        if (thrust > 0.10) thrust = 0.10;
      }
      lastThrust = thrust;

      out.thrust = thrust;
      out.roll = roll;
      out.pitch = pitch;
      out.yawRate = clamp(-3.2 * att.yaw - 2.5 * yawInt - 0.25 * rates.yaw, -2, 2);
      return out;
    },
  };
}

